import{_ as s,l,o as a,c as i,v as r,p as n,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Kerberos 直觉","description":"","frontmatter":{"title":"Kerberos 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kerberos.md","filePath":"cs/kerberos.md","lastUpdated":1789023840000}'),p={name:"cs/kerberos.md"};function A(T,e,_,b,S,m){const o=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=r('<h1 id="kerberos-直觉" tabindex="-1">Kerberos 直觉 <a class="header-anchor" href="#kerberos-直觉" aria-label="Permalink to &quot;Kerberos 直觉&quot;">​</a></h1><div class="epigraph"><p>用密钥分发中心发有时限的票据：一次登录，向许多服务证明自己，而不把长期口令送给每一台服务器。</p><footer>—— 据 Needham–Schroeder；MIT Kerberos；Stallings；RFC 4120 对照</footer></div><p><a href="/cs/auth-protocol">上一课</a>抽出挑战–响应与抗重放。本课不重做「认证不是加密」。缺口是域内单点：许多服务器共享用户口令会扩大泄露面。Kerberos：可信 KDC 发票据与会话键，服务只验证票。OAuth 下一课是互联网上的委托，对象不同。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>认证协议课留下通用消息。局域网要 SSO。Needham–Schroeder 对称方案的时间戳/nonce 修补通向 Kerberos：AS 用长期密钥（常从口令派生）交出 TGT；TGS 用 TGT 发服务票。服务票含会话键与名字、期限。缺口是<strong>票据作为能力的直觉</strong>，不是把报文格式背完。</p><p><span class="marginnote">时钟同步是 Kerberos 的著名假设：期限与防重放靠时间窗。KDC 是单点信任与单点故障。本课不给伪造票步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>登录：用户向 AS 证明，得 TGT。访问服务：持 TGT 向 TGS 要服务票，再向服务出示。服务用自己与 KDC 的共享键打开票。后课能力对 ACL 会对照「持票即允许」。TLS 不替代域内这套，对象是浏览器与网站时另一套。</p>',8)),(a(),n(c,null,{default:t(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%22%5D%20--%3E%20AS%5B%22AS%20%E5%8F%91%20TGT%22%5D%0A%20%20AS%20--%3E%20TGS%5B%22TGS%20%E5%8F%91%E6%9C%8D%E5%8A%A1%E7%A5%A8%22%5D%0A%20%20TGS%20--%3E%20SV%5B%22%E6%9C%8D%E5%8A%A1%E9%AA%8C%E8%AF%81%E7%A5%A8%E4%B8%8E%E6%9C%9F%E9%99%90%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>长期秘密只在用户与 KDC、服务与 KDC 之间；服务不存用户口令。这缩小泄露面，并把<a href="/cs/acl-least-priv">最小特权</a> 做成有期限的会话键。DY 敌手无 KDC 密钥则不能铸造合法票。时钟与重放窗口是模型的一部分。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把跨域信任传递的全部 krbtgt 故事写进主干。浏览器委托第三方访问 API，下一课 OAuth/OIDC。</p><p>后课默认：域内票据是一种认证。开放 Web 上的授权委托是另一协议族。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kerberos：KDC 发有时限票据与会话键。</li><li>服务不收用户长期口令。</li><li>OAuth/OIDC 下一课。</li><li>出处：Needham–Schroeder；Stallings；RFC 4120。</li></ul>',7))])}const E=s(p,[["render",A]]);export{C as __pageData,E as default};
